import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";
import "./Profile.css"; // custom CSS

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software Engineer",
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software Engineer"
          });
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem("token");
    if (!token) return;

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: {
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("✅ Profile updated successfully!");
      } else {
        setMessage("❌ Failed to update profile");
      }
    } catch (err) {
      console.error(err);
      setMessage("⚠️ Network error. Try again later.");
    }
  };

  if (loading) return (
    <div className="loading-container">
      <div className="loading-spinner"></div>
      <p>Loading profile...</p>
    </div>
  );

  return (
    <div className="profile-wrapper">
      {/* Left Side - Profile Form */}
      <div className="profile-content">
        <div className="profile-header">
          <h1 className="profile-title">My Profile</h1>
          <p className="profile-subtitle">Manage your personal information and preferences</p>
        </div>

        <form onSubmit={handleSubmit} className="profile-form">
          <div className="form-row">
            <div className="form-group">
              <label className="form-label">
                <i className="icon-user"></i>
                Full Name
              </label>
              <input
                type="text"
                className="form-control-modern"
                name="fullName"
                value={profile.fullName}
                onChange={handleChange}
                placeholder="Enter your full name"
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">
                <i className="icon-mail"></i>
                Email Address
              </label>
              <input
                type="email"
                className="form-control-modern"
                name="email"
                value={profile.email}
                onChange={handleChange}
                placeholder="your@email.com"
                required
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label">
                <i className="icon-phone"></i>
                Phone Number
              </label>
              <input
                type="tel"
                className="form-control-modern"
                name="phone"
                value={profile.phone}
                onChange={handleChange}
                placeholder="+1 (555) 123-4567"
              />
            </div>

            <div className="form-group">
              <label className="form-label">
                <i className="icon-briefcase"></i>
                Role
              </label>
              <input
                type="text"
                className="form-control-modern role-input"
                value={profile.role}
                readOnly
              />
            </div>
          </div>

          <div className="form-group full-width">
            <label className="form-label">
              <i className="icon-edit"></i>
              Bio
            </label>
            <textarea
              className="form-control-modern bio-textarea"
              name="bio"
              rows="4"
              value={profile.bio}
              onChange={handleChange}
              placeholder="Tell us about yourself..."
            ></textarea>
          </div>

          <div className="form-actions">
            <button type="submit" className="btn-save">
              <span className="btn-text">Save Changes</span>
              <div className="btn-bg"></div>
            </button>
            {message && <div className="message-container">
              <p className="message">{message}</p>
            </div>}
          </div>
        </form>
      </div>

      {/* Right Side - Modern Illustration */}
      <div className="profile-illustration">
        <div className="illustration-container">
          <div className="decoration-circle circle-1"></div>
          <div className="decoration-circle circle-2"></div>
          <div className="decoration-circle circle-3"></div>
          
          <img
            src="https://images.unsplash.com/photo-1557426272-fc759fdf7a8d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80"
            alt="Modern workspace illustration"
            className="main-illustration"
          />
          
          <div className="floating-elements">
            <div className="floating-card card-1">
              <div className="card-icon">📊</div>
              <div className="card-text">Analytics</div>
            </div>
            <div className="floating-card card-2">
              <div className="card-icon">⚡</div>
              <div className="card-text">Performance</div>
            </div>
            <div className="floating-card card-3">
              <div className="card-icon">🎯</div>
              <div className="card-text">Goals</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
